// Authored A2 curriculum, Unit 1: narrating past events.
// This is an incremental content bank: the full A2 level is not yet complete.
Map<String, dynamic> _lesson(
  int n, String title, String explanation, String example, String french,
  String question, List<String> options, int answer, String correction,
) => <String, dynamic>{
  'id': 'A2-U01-L${n.toString().padLeft(2, '0')}',
  'level': 'A2', 'title': title, 'subtitle': 'Raconter le passé • Leçon $n/50',
  'explanation': explanation, 'example': example, 'french': french,
  'question': question, 'options': options, 'answer': answer,
  'correction': correction, 'unit': 1, 'phase': 0,
};

final List<Map<String, dynamic>> a2CourseData = <Map<String, dynamic>>[
  _lesson(1, 'Le passé de be : was et were', 'Was s’emploie avec I, he, she et it ; were avec you, we et they.', 'I was tired. They were ready.', 'J’étais fatigué. Ils étaient prêts.', 'Complète : We ___ at school yesterday.', ['was','were','are'], 1, 'We prend were au passé.'),
  _lesson(2, 'Décrire un état passé', 'Pour décrire un état terminé dans le passé, utilise was/were suivi d’un adjectif.', 'The classroom was quiet.', 'La salle de classe était calme.', 'Choisis la phrase correcte.', ['The room were quiet.','The room was quiet.','The room did quiet.'], 1, 'Room est singulier : was quiet.'),
  _lesson(3, 'Nier avec wasn’t et weren’t', 'Was not devient wasn’t ; were not devient weren’t. On ne place pas did avec be.', 'She wasn’t angry.', 'Elle n’était pas fâchée.', 'Complète : They ___ late.', ['wasn’t','weren’t','didn’t were'], 1, 'They prend weren’t.'),
  _lesson(4, 'Questions avec was et were', 'Dans une question avec be au passé, place was ou were avant le sujet.', 'Were you at the meeting?', 'Étais-tu à la réunion ?', 'Quelle question est correcte ?', ['Did you were there?','Were you there?','You was there?'], 1, 'Were se place avant you.'),
  _lesson(5, 'Réponses courtes avec be', 'Réponds à une question avec be en reprenant was ou were dans une réponse courte.', '“Was he home?” “No, he wasn’t.”', '« Était-il à la maison ? » « Non. »', 'Réponds oui : “Were they ready?”', ['Yes, they did.','Yes, they were.','Yes, they was.'], 1, 'La réponse courte reprend were.'),
  _lesson(6, 'Le passé régulier en -ed', 'La plupart des verbes réguliers prennent -ed au past simple, quelle que soit la personne.', 'We watched a documentary.', 'Nous avons regardé un documentaire.', 'Quel est le passé de watch ?', ['watching','watched','watchs'], 1, 'Watch devient watched.'),
  _lesson(7, 'Verbes qui finissent par e', 'Si le verbe finit par e, ajoute généralement seulement -d.', 'Lina arrived before noon.', 'Lina est arrivée avant midi.', 'Complète : He ___ at eight. (arrive)', ['arrived','arriveed','arrives'], 0, 'Arrive devient arrived.'),
  _lesson(8, 'Consonne + y au passé', 'Pour un verbe régulier terminé par consonne + y, remplace y par i puis ajoute -ed.', 'I studied after dinner.', 'J’ai étudié après le dîner.', 'Quelle forme est correcte ?', ['studyed','studied','studyd'], 1, 'Study devient studied.'),
  _lesson(9, 'Doubler une consonne finale', 'Certains verbes courts doublent leur consonne finale avant -ed, comme stop → stopped.', 'The bus stopped near the school.', 'Le bus s’est arrêté près de l’école.', 'Choisis l’orthographe correcte.', ['stoped','stopped','stoppied'], 1, 'Stopped prend deux p.'),
  _lesson(10, 'Les trois sons de -ed', 'La terminaison -ed peut se prononcer /t/, /d/ ou /ɪd/. Après les sons /t/ et /d/, elle ajoute une syllabe.', 'worked /t/, played /d/, wanted /ɪd/.', 'Ces trois verbes ont trois prononciations de -ed.', 'Dans quel mot -ed ajoute-t-il une syllabe ?', ['washed','wanted','played'], 1, 'Wanted se termine par le son /ɪd/.'),
  _lesson(11, 'Go devient went', 'Go est irrégulier : son past simple est went, et non goed.', 'We went to the market on Saturday.', 'Nous sommes allés au marché samedi.', 'Complète : Yesterday, I ___ home early.', ['goed','went','go'], 1, 'Went est le passé de go.'),
  _lesson(12, 'Have devient had', 'Have devient had au passé pour toutes les personnes.', 'She had a headache yesterday.', 'Elle avait mal à la tête hier.', 'They ___ lunch at noon.', ['has','had','have'], 1, 'Had est la forme passée de have.'),
  _lesson(13, 'Do devient did', 'Did est le passé de do. Dans une affirmation, il peut être le verbe principal.', 'I did my homework.', 'J’ai fait mes devoirs.', 'Quel est le passé de do ?', ['does','did','done'], 1, 'Did est le past simple de do.'),
  _lesson(14, 'See devient saw', 'See devient saw au past simple ; seen est le participe passé utilisé avec have/has.', 'We saw a rainbow after the rain.', 'Nous avons vu un arc-en-ciel après la pluie.', 'This morning, I ___ your teacher.', ['seen','saw','see'], 1, 'Saw est le passé simple de see.'),
  _lesson(15, 'Eat devient ate', 'Eat devient ate au passé pour parler d’un repas ou d’un aliment consommé.', 'He ate rice for lunch.', 'Il a mangé du riz à midi.', 'Yesterday, she ___ an orange.', ['eated','ate','eats'], 1, 'Ate est le passé de eat.'),
  _lesson(16, 'Buy devient bought', 'Le verbe buy, acheter, devient bought au passé.', 'My sister bought a notebook.', 'Ma sœur a acheté un cahier.', 'Quel est le passé de buy ?', ['buyed','bought','buys'], 1, 'Bought est le passé de buy.'),
  _lesson(17, 'Make devient made', 'Make devient made ; selon le contexte, il signifie fabriquer, préparer ou créer.', 'Dad made breakfast.', 'Papa a préparé le petit-déjeuner.', 'We ___ a poster yesterday.', ['maked','made','make'], 1, 'Made est le passé de make.'),
  _lesson(18, 'Take devient took', 'Take devient took au past simple. On dit take a photo, take a bus ou take a seat.', 'I took a photo of the river.', 'J’ai pris une photo de la rivière.', 'Quel est le passé de take ?', ['taked','took','taken'], 1, 'Took est le past simple ; taken est le participe passé.'),
  _lesson(19, 'Come devient came', 'Come devient came au passé et décrit un déplacement vers le lieu de référence.', 'Our cousins came last month.', 'Nos cousins sont venus le mois dernier.', 'Nina ___ home late last night.', ['came','comed','comes'], 0, 'Came est le passé de come.'),
  _lesson(20, 'Get devient got', 'En anglais américain, got est le passé courant de get, qui peut signifier recevoir, obtenir ou devenir.', 'I got your message this morning.', 'J’ai reçu ton message ce matin.', 'I got your message signifie :', ['Je t’ai envoyé un message.','J’ai reçu ton message.','J’ai oublié ton message.'], 1, 'Got signifie ici reçu.'),
  _lesson(21, 'Yesterday et last night', 'Yesterday signifie hier ; last night signifie hier soir ou la nuit dernière selon le contexte.', 'We studied yesterday.', 'Nous avons étudié hier.', 'Quel mot signifie « hier » ?', ['tomorrow','yesterday','tonight'], 1, 'Yesterday signifie hier.'),
  _lesson(22, 'Dire « il y a » avec ago', 'Place ago après une durée pour dire « il y a » : two days ago, three hours ago.', 'The train left ten minutes ago.', 'Le train est parti il y a dix minutes.', 'Complète : I called you two days ___.', ['ago','last','next'], 0, 'Ago se place après la durée.'),
  _lesson(23, 'Employer last avec une période', 'Last accompagne une période précédente : last week, last month, last year.', 'They moved here last year.', 'Ils ont déménagé ici l’année dernière.', 'Comment dire « la semaine dernière » ?', ['next week','last week','week ago last'], 1, 'Last week signifie la semaine dernière.'),
  _lesson(24, 'Négation avec didn’t', 'Pour nier une action passée, utilise didn’t + base verbale, jamais le verbe au passé après didn’t.', 'She didn’t call me.', 'Elle ne m’a pas appelé.', 'He didn’t ___ the answer.', ['knew','know','knows'], 1, 'Après didn’t, utilise know.'),
  _lesson(25, 'Choisir didn’t ou wasn’t', 'Utilise didn’t avec un verbe d’action et wasn’t avec be pour un état ou un lieu au passé.', 'I didn’t work. I wasn’t at work.', 'Je n’ai pas travaillé. Je n’étais pas au travail.', 'Lena ___ at home; she was at school.', ['didn’t was','wasn’t','didn’t be'], 1, 'Wasn’t est la négation de was.'),
  _lesson(26, 'Questions avec did', 'Pour interroger sur une action passée, utilise Did + sujet + base verbale.', 'Did you finish the exercise?', 'As-tu terminé l’exercice ?', 'Quelle question est correcte ?', ['Did she arrived?','Did she arrive?','Does she arrived?'], 1, 'Après did, arrive reste à la base.'),
  _lesson(27, 'Réponses courtes avec did', 'Réponds à Did…? par Yes, … did ou No, … didn’t.', '“Did Mark call?” “Yes, he did.”', '« Mark a-t-il appelé ? » « Oui. »', 'Réponds non à “Did you see it?”', ['No, I wasn’t.','No, I didn’t.','No, I don’t.'], 1, 'La réponse reprend did à la forme négative.'),
  _lesson(28, 'Questions avec what et where', 'Place le mot interrogatif avant did, puis le sujet et la base verbale.', 'Where did they stay?', 'Où ont-ils séjourné ?', 'What did you ___?', ['bought','buy','buying'], 1, 'Après did you, utilise buy.'),
  _lesson(29, 'Who comme sujet', 'Quand who est le sujet de l’action, on n’emploie généralement pas did : Who called? ', 'Who opened the door?', 'Qui a ouvert la porte ?', 'Quelle question est correcte ?', ['Who did called?','Who called?','Who was call?'], 1, 'Who est le sujet de called.'),
  _lesson(30, 'Distinguer was et did', 'Was/were servent avec be ; did sert à construire les questions sur les verbes d’action.', 'Was the shop open? Did you buy bread?', 'Le magasin était-il ouvert ? As-tu acheté du pain ?', 'Quelle question porte sur une action ?', ['Were you tired?','Was it cold?','Did you buy bread?'], 2, 'Buy est un verbe d’action.'),
  _lesson(31, 'Raconter dans l’ordre', 'First, then, after that et finally organisent un récit dans l’ordre chronologique.', 'First I got up, then I showered, and finally I left.', 'D’abord je me suis levé, ensuite je me suis douché et enfin je suis parti.', 'Quel mot annonce la dernière étape ?', ['First','Finally','Because'], 1, 'Finally indique la dernière étape.'),
  _lesson(32, 'Relier des actions avec after that', 'After that signifie « après cela » et relie deux événements successifs.', 'We ate dinner. After that, we watched a film.', 'Nous avons dîné. Après cela, nous avons regardé un film.', 'We finished class. ___, we went home.', ['After that','Although','Unless'], 0, 'After that indique la suite chronologique.'),
  _lesson(33, 'Utiliser when dans un récit', 'When signifie « quand/lorsque » et situe un événement par rapport à un autre.', 'When I arrived, the lesson started.', 'Quand je suis arrivé, le cours a commencé.', 'When we ___, the rain stopped.', ['arrive','arrived','arriving'], 1, 'Arrived situe l’arrivée dans le passé.'),
  _lesson(34, 'Exprimer une durée avec for', 'For + durée précise combien de temps une action a duré.', 'We waited for thirty minutes.', 'Nous avons attendu pendant trente minutes.', 'Quelle expression donne une durée ?', ['at noon','for two hours','last Monday'], 1, 'For two hours signifie pendant deux heures.'),
  _lesson(35, 'Distinguer for et during', 'For est suivi d’une durée ; during est suivi d’un événement ou d’une période nommée.', 'I fell asleep during the movie.', 'Je me suis endormi pendant le film.', 'We talked ___ the break.', ['during','for','ago'], 0, 'The break est une période nommée.'),
  _lesson(36, 'Exprimer une émotion passée', 'Utilise was/were + adjectif pour décrire une émotion ou un état passé.', 'I was nervous before the interview.', 'J’étais nerveux avant l’entretien.', 'The students ___ proud.', ['was','were','did'], 1, 'Students est pluriel : were.'),
  _lesson(37, 'Décrire la météo passée', 'Pour la météo, utilise it was + adjectif ou un verbe comme rained.', 'It was cloudy, but it didn’t rain.', 'Le ciel était couvert, mais il n’a pas plu.', 'Choisis la phrase correcte.', ['It were cold.','It was cold.','It did cold.'], 1, 'Avec it, on emploie was.'),
  _lesson(38, 'Leave devient left', 'Leave devient left au passé et signifie partir ou quitter.', 'We left home at seven.', 'Nous avons quitté la maison à sept heures.', 'Quel est le passé de leave ?', ['leaved','left','leaving'], 1, 'Left est le passé irrégulier de leave.'),
  _lesson(39, 'Raconter un achat', 'Pour raconter un achat terminé, utilise bought et ajoute si utile le lieu ou le moment.', 'I bought these shoes yesterday.', 'J’ai acheté ces chaussures hier.', 'We ___ two notebooks yesterday.', ['buy','bought','buyed'], 1, 'Bought est le passé de buy.'),
  _lesson(40, 'Parler d’un repas', 'Have breakfast/lunch/dinner est une expression courante ; had est la forme passée de have.', 'They had dinner with their grandparents.', 'Ils ont dîné avec leurs grands-parents.', 'Comment dire « prendre le petit-déjeuner » ?', ['do breakfast','have breakfast','eat breakfasting'], 1, 'Have breakfast est l’expression standard.'),
  _lesson(41, 'Donner une raison avec because', 'Because introduit la raison d’une action.', 'I stayed home because I felt sick.', 'Je suis resté chez moi parce que je me sentais malade.', 'Pourquoi la personne est-elle restée chez elle ?', ['Because she felt sick.','Because she will travel.','Because she feels fine now.'], 0, 'Because introduit la raison.'),
  _lesson(42, 'Exprimer un contraste avec but', 'But signifie « mais » et relie deux idées qui contrastent.', 'It was expensive, but I bought it.', 'C’était cher, mais je l’ai acheté.', 'Quel mot exprime un contraste ?', ['so','but','because'], 1, 'But signifie mais.'),
  _lesson(43, 'Exprimer une conséquence avec so', 'So peut signifier « donc/alors » et introduire le résultat d’une situation.', 'The road was closed, so we took another route.', 'La route était fermée, donc nous avons pris un autre itinéraire.', 'I missed the bus, ___ I walked to school.', ['so','although','unless'], 0, 'So introduit la conséquence.'),
  _lesson(44, 'Raconter une visite', 'Utilise visited ou went to pour parler d’une visite terminée, puis ajoute des détails.', 'We visited our grandmother on Sunday.', 'Nous avons rendu visite à notre grand-mère dimanche.', 'Quelle phrase décrit une visite passée ?', ['We visit her tomorrow.','We visited her on Sunday.','We are visiting her last year.'], 1, 'Visited indique une action passée terminée.'),
  _lesson(45, 'Problème et solution', 'Dans un récit clair, présente le problème puis la solution ; so peut relier les deux.', 'My phone stopped working, so I borrowed my brother’s phone.', 'Mon téléphone a cessé de fonctionner, alors j’ai emprunté celui de mon frère.', 'Quelle solution est donnée ?', ['Borrowed a phone','Bought a car','Missed a class'], 0, 'Le locuteur a emprunté un téléphone.'),
  _lesson(46, 'Comprendre un court récit', 'Repère les marqueurs de temps, les personnes et les verbes au passé pour comprendre la chronologie.', 'Ella missed the bus and arrived late at the party.', 'Ella a raté le bus et est arrivée en retard à la fête.', 'Why was Ella late?', ['She missed the bus.','She forgot her name.','She arrived early.'], 0, 'Le récit précise qu’elle a raté le bus.'),
  _lesson(47, 'Éviter les erreurs après did', 'Après did ou didn’t, utilise la base verbale : did go, didn’t see, did buy.', 'Correct: Did you go? Not: Did you went?', 'Correct : Es-tu allé ? et non « Did you went ? »', 'Quelle phrase est correcte ?', ['Did you went home?','Did you go home?','Did you going home?'], 1, 'Après did, le verbe reste à la base.'),
  _lesson(48, 'Passé ou habitude présente', 'Yesterday appelle généralement le passé ; every day décrit souvent une habitude au présent.', 'I walk every day, but yesterday I took the bus.', 'Je marche chaque jour, mais hier j’ai pris le bus.', 'Quelle forme convient avec every day ?', ['walk','walked yesterday','walking'], 0, 'Every day indique une habitude présente.'),
  _lesson(49, 'Organiser un paragraphe passé', 'Un paragraphe au passé garde une chronologie claire et utilise des connecteurs simples.', 'Yesterday I cleaned my room, then I studied, and finally I watched a film.', 'Hier, j’ai rangé ma chambre, puis étudié et enfin regardé un film.', 'Quel connecteur introduit la dernière action ?', ['Then','Finally','Because'], 1, 'Finally présente la dernière action.'),
  _lesson(50, 'Bilan : raconter sa journée', 'Révise was/were, les verbes réguliers et irréguliers, les questions avec did et les connecteurs chronologiques.', 'Last Saturday, I got up early, visited my uncle, and came home before dark.', 'Samedi dernier, je me suis levé tôt, j’ai rendu visite à mon oncle et je suis rentré avant la nuit.', 'Quelle phrase raconte correctement le passé ?', ['Last Saturday I get up and come home.','Last Saturday I got up and came home.','Last Saturday I did got up.'], 1, 'Got et came sont les formes passées correctes.'),
];
